// Tier 1 — SEO artifacts (head blocks, vs-pages, sitemap, robots) are
// generated by scripts/generate-seo.js and committed. These tests
// regenerate everything in memory and fail on any drift, so a data or
// site-config edit without a generator rerun cannot land silently.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('fs');
const path = require('path');
const { loadBrand, brandDirs, ROOT } = require('../helpers/load-brand');
const { buildAll, curatedPairs, siteConfig,
        ID_HEAD_BEGIN, ID_HEAD_END, ID_HEADER_BEGIN, ID_HEADER_END } = require('../../scripts/generate-seo');

const generated = buildAll();

test('trust pages carry both identity marker pairs (generator refuses to write without them)', () => {
  for (const page of ['about.html', 'privacy.html']) {
    const html = fs.readFileSync(path.join(ROOT, page), 'utf8');
    for (const marker of [ID_HEAD_BEGIN, ID_HEAD_END, ID_HEADER_BEGIN, ID_HEADER_END]) {
      assert.ok(html.includes(marker), `${page}: missing identity marker ${marker}`);
    }
    assert.ok(generated.has(page), `${page} must be part of the generator's output set`);
  }
});

test('every generated artifact matches the committed file (rerun scripts/generate-seo.js)', () => {
  for (const [rel, content] of generated) {
    const abs = path.join(ROOT, rel);
    assert.ok(fs.existsSync(abs), `${rel} missing — run: node scripts/generate-seo.js`);
    assert.equal(fs.readFileSync(abs, 'utf8'), content,
      `${rel} is stale — run: node scripts/generate-seo.js`);
  }
});

test('no orphan vs-pages on disk beyond the curated set', () => {
  for (const brand of brandDirs()) {
    const vsDir = path.join(ROOT, brand, 'vs');
    if (!fs.existsSync(vsDir)) continue;
    for (const f of fs.readdirSync(vsDir)) {
      assert.ok(generated.has(`${brand}/vs/${f}`),
        `${brand}/vs/${f} is not in the curated set — run: node scripts/generate-seo.js`);
    }
  }
});

test('sitemap covers root, every brand page, every vs-page, and trust pages', () => {
  const sitemap = generated.get('sitemap.xml');
  const site = siteConfig();
  assert.ok(sitemap.includes(`<loc>${site.baseUrl}/</loc>`));
  for (const p of ['about.html', 'privacy.html']) {
    assert.ok(sitemap.includes(`<loc>${site.baseUrl}/${p}</loc>`), `sitemap missing ${p}`);
  }
  for (const brand of brandDirs()) {
    assert.ok(sitemap.includes(`<loc>${site.baseUrl}/${brand}/</loc>`), `sitemap missing ${brand}/`);
    for (const [rel] of generated) {
      if (rel.startsWith(`${brand}/vs/`)) {
        assert.ok(sitemap.includes(`<loc>${site.baseUrl}/${rel}</loc>`), `sitemap missing ${rel}`);
      }
    }
  }
});

test('robots.txt allows crawling and references the sitemap', () => {
  const robots = generated.get('robots.txt');
  assert.ok(robots.includes('Allow: /'));
  assert.ok(robots.includes(`Sitemap: ${siteConfig().baseUrl}/sitemap.xml`));
});

test('base URL appears only via site-config (canonicals all start with it)', () => {
  const { baseUrl } = siteConfig();
  assert.match(baseUrl, /^https:\/\//);
  for (const [rel, content] of generated) {
    if (!rel.endsWith('.html')) continue;
    const m = content.match(/<link rel="canonical" href="([^"]+)"/);
    assert.ok(m, `${rel} has no canonical`);
    assert.ok(m[1].startsWith(baseUrl), `${rel} canonical ${m[1]} not under baseUrl`);
  }
});

for (const brand of brandDirs()) {
  test(`[${brand}] curated pairs are sane (deduped, valid slugs, far below all-pairs)`, () => {
    const { data } = loadBrand(brand);
    const cams = data.CAMERAS;
    const pairs = curatedPairs(cams);
    const n = Object.keys(cams).length;
    const allPairs = (n * (n - 1)) / 2;
    assert.ok(pairs.length > 0, 'expected at least one curated pair');
    assert.ok(pairs.length <= Math.max(45, allPairs / 3),
      `${pairs.length} pages for ${n} cameras looks like thin-content explosion (all-pairs: ${allPairs})`);
    const keys = new Set();
    for (const [a, b] of pairs) {
      assert.ok(cams[a] && cams[b], `pair references unknown slug: ${a} / ${b}`);
      assert.notEqual(a, b);
      const key = [a, b].sort().join('|');
      assert.ok(!keys.has(key), `duplicate pair ${key}`);
      keys.add(key);
    }
  });

  test(`[${brand}] vs-pages deep-link with valid shareable hashes`, () => {
    const { data } = loadBrand(brand);
    for (const [rel, content] of generated) {
      if (!rel.startsWith(`${brand}/vs/`)) continue;
      const m = content.match(/href="\.\.\/index\.html#cameras=([^"]+)"/);
      assert.ok(m, `${rel} has no interactive-tool deep link`);
      for (const slug of m[1].split(',')) {
        assert.ok(data.CAMERAS[slug], `${rel} deep-links to unknown camera "${slug}"`);
      }
    }
  });
}
